import React, { useState } from 'react';

// Define the Todo interface here
interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

// Create the TodoList component here
const TodoList = () => {
  // Initialize todos state here
  const [todos, setTodos] = useState<Todo[]>([]);

  // Initialize inputText state here
  const [inputText, setInputText] = useState<string>('');

  // Define handleAddTodo function here
  const handleAddTodo = () => {
    if (inputText.trim() !== '') {
      const newTodo: Todo = {
        id: Date.now(),
        text: inputText,
        completed: false
      };
      setTodos([...todos, newTodo]);
      setInputText('');
    }
  };

  // Define handleToggleTodo function here
  const handleToggleTodo = (id: number) => {
    setTodos(todos.map(todo => 
      todo.id === id ? { ...todo, completed: !todo.completed } : todo
    ));
  };

  // Define handleDeleteTodo function here
  const handleDeleteTodo = (id: number) => {
    setTodos(todos.filter(todo => todo.id !== id));
  };

  return (
    <div>
      <h1>Todo List</h1>
      <div>
        <input
          type="text"
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          placeholder="Add a new todo"
        />
        <button onClick={handleAddTodo}>Add</button>
      </div>
      <ul>
        {todos.map(todo => (
          <li key={todo.id}>
            <span style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}>
              {todo.text}
            </span>
            {/* Add toggle and delete buttons here */}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default TodoList;
